// Dipicu oleh output status dari Process Sensor.
// Data lengkap sudah disimpan Process Sensor di flow.jsiaga_latest.
const latest = flow.get('jsiaga_latest');
const token = env.get('JSIAGA_DEVICE_TOKEN');
const baseUrl = env.get('JSIAGA_LARAVEL_URL') || 'http://IP_LAPTOP:8000';

if (!latest || !Number.isFinite(Number(latest.distance))) {
    node.warn('Laravel bridge: data sensor terbaru belum tersedia');
    return [null, { payload: { success: false, message: 'Data sensor terbaru belum tersedia' } }];
}

if (!token) {
    node.warn('Laravel bridge: JSIAGA_DEVICE_TOKEN belum diatur');
    return [null, { payload: { success: false, message: 'JSIAGA_DEVICE_TOKEN belum diatur di environment Node-RED' } }];
}

const nullableNumber = (value) =>
    value === null || value === undefined || !Number.isFinite(Number(value))
        ? null
        : Number(value);

msg.method = 'POST';
msg.url = baseUrl.replace(/\/$/, '') + '/api/v1/sensor-readings';
msg.headers = {
    'Content-Type': 'application/json',
    'Accept': 'application/json',
    'X-Device-Token': token
};
msg.payload = {
    distance: Number(latest.distance),
    temperature: nullableNumber(latest.temperature),
    humidity: nullableNumber(latest.humidity),
    light: nullableNumber(latest.light),
    recorded_at: latest.updatedAt || new Date().toISOString()
};

return [msg, null];
